"use client";

import React, { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  SignInButton,
  SignUpButton,
  SignedIn,
  SignedOut,
  UserButton,
} from "@clerk/nextjs";
import { useChatStore } from "@/lib/store/chat";

interface NavbarMenuProps {
  isMenuOpen: boolean;
  onMenuClick: () => void;
  onClose: () => void;
  historyItems: Array<{ name: string; href: string }>;
}

type HistoryItem = { id: string; name: string; href: string; updatedAt?: number };
type ChatMessage = { id: string; role: "user" | "assistant"; content: string; modelId?: string };

const NavbarMenu: React.FC<NavbarMenuProps> = ({
  isMenuOpen,
  onMenuClick,
  onClose,
  historyItems: _ignored,
}) => {
  const pathname = usePathname();
  const router = useRouter();
  const onStatistics = pathname?.startsWith("/statistics");

  // actions từ store
  const { setMessages, setCurrentThreadId, clearMessages } = useChatStore();

  // ===== Lịch sử =====
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [histErr, setHistErr] = useState<string | null>(null);

  useEffect(() => {
    const onEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isMenuOpen) onClose();
    };
    window.addEventListener("keydown", onEsc);
    return () => window.removeEventListener("keydown", onEsc);
  }, [isMenuOpen, onClose]);

  // fetch lịch sử khi mở menu
  useEffect(() => {
    if (!isMenuOpen) return;
    let cancelled = false;
    (async () => {
      setLoadingHistory(true);
      setHistErr(null);
      try {
        const res = await fetch("/api/chat-history", { cache: "no-store" });
        if (!res.ok) throw new Error(await res.text());
        const data: HistoryItem[] = await res.json();
        if (!cancelled) setHistory(data);
      } catch (e: any) {
        if (!cancelled) setHistErr(e?.message ?? "Không tải được lịch sử");
      } finally {
        if (!cancelled) setLoadingHistory(false);
      }
    })();
    return () => { cancelled = true; };
  }, [isMenuOpen]);

  // mở 1 thread có sẵn
  const handleOpenChat = async (threadId: string) => {
    try {
      const res = await fetch(`/api/chat-history/${threadId}`, { cache: "no-store" });
      if (!res.ok) throw new Error(await res.text());
      const data: { id: string; messages: ChatMessage[] } = await res.json();

      setMessages(Array.isArray(data.messages) ? data.messages : []);
      setCurrentThreadId(data.id);
      onClose();
      if (pathname !== "/") router.push("/");
    } catch (e: any) {
      alert(e?.message ?? "Không mở được đoạn chat này.");
    }
  };

  // ====== NÚT ĐOẠN CHAT MỚI (LÀM MỚI) – chỉ reset frontend ======
  const handleNewChat = () => {
    clearMessages();            // xóa messages + reset currentThreadId trong store
    onClose();
    if (pathname !== "/") router.push("/"); // quay về trang chủ nếu đang ở trang khác
  };

  return (
    <nav className="bg-[#BBDCE5] text-white shadow-lg fixed top-0 left-0 right-0 z-[100] h-16">
      <div className="flex items-center justify-between px-4 h-full max-w-8xl mx-auto">
        {/* Trái */}
        <div className="flex items-center gap-2 w-60">
          <button
            onClick={onMenuClick}
            className={`p-2 rounded-md text-xl transition-colors duration-150 ${
              isMenuOpen ? "opacity-0 pointer-events-none" : "hover:bg-[#D0E8F2]"
            }`}
            aria-label="Mở menu"
            aria-expanded={isMenuOpen}
            aria-controls="side-menu"
          >
            ☰
          </button>

          {onStatistics && (
            <Link
              href="/"
              className="px-3 py-2 rounded-md bg-white/20 hover:bg-white/40 transition text-sm md:text-base"
              aria-label="Về trang chủ"
            >
              ← Trang chủ
            </Link>
          )}
        </div>

        {/* Tiêu đề */}
        <h1 className="text-lg font-bold whitespace-nowrap">Ask Them All</h1>

        {/* Phải: auth */}
        <div className="flex justify-end w-60">
          <div className="flex items-center gap-2">
            <SignedOut>
              <SignInButton />
              <SignUpButton>
                <button className="bg-[#456268] text-ceramic-white rounded-full font-medium text-sm sm:text-base h-10 sm:h-12 px-4 sm:px-5 cursor-pointer">
                  Sign Up
                </button>
              </SignUpButton>
            </SignedOut>
            <SignedIn>
              <UserButton />
            </SignedIn>
          </div>
        </div>
      </div>

      {/* Overlay */}
      <div
        onClick={onClose}
        aria-hidden="true"
        className={[
          "fixed inset-0 z-[90] transition-opacity duration-200 ease-out",
          isMenuOpen
            ? "opacity-100 pointer-events-auto bg-black/40"
            : "opacity-0 pointer-events-none bg-black/40",
        ].join(" ")}
      />

      {/* Side menu */}
      <aside
        id="side-menu"
        role="dialog"
        aria-modal="true"
        aria-label="Menu điều hướng"
        className={[
          "fixed top-0 left-0 z-[95] h-full w-72 max-w-[90vw] bg-[#BBDCE5] p-4 shadow-xl",
          "transform-gpu [will-change:transform] transition-transform duration-400 ease-out",
          isMenuOpen ? "translate-x-0" : "-translate-x-full",
        ].join(" ")}
      >
        <div className="flex justify-end mb-4 mt-16">
          <button
            onClick={onClose}
            className="p-2 bg-[#456268] rounded hover:bg-[#D0E8F2] transition-colors duration-700"
          >
            Đóng
          </button>
        </div>

        {/* Chức năng */}
        <div className="mb-6">
          <h2 className="text-2xl font-bold mb-4">Chức năng</h2>
          <ul className="space-y-4 text-xl">
            <li>
              <a
                href="/statistics"
                onClick={onClose}
                className="block hover:underline focus:outline-none focus:ring-2 focus:ring-white/10 rounded-sm transition"
              >
                Thống kê
              </a>
            </li>

            {/* ✅ Nút Đoạn chat mới (làm mới) */}
            <li>
              <button
                onClick={handleNewChat}
                className="w-full text-left block hover:underline focus:outline-none focus:ring-2 focus:ring-white/10 rounded-sm transition"
                title="Bắt đầu đoạn chat mới (không xóa dữ liệu trong DB)"
              >
                Đoạn chat mới
              </button>
            </li>
          </ul>
        </div>

        {/* Lịch sử */}
        <div>
          <h2 className="text-2xl font-bold mb-2">Lịch sử</h2>
          {loadingHistory ? (
            <div className="text-sm opacity-80">Đang tải…</div>
          ) : histErr ? (
            <div className="text-sm text-red-700">{histErr}</div>
          ) : (
            <ul className="space-y-3 text-base max-h-[50vh] overflow-y-auto pr-1">
              {history.length === 0 ? (
                <li className="text-sm opacity-80">Chưa có lịch sử</li>
              ) : (
                history.map((item) => (
                  <li key={item.id}>
                    <button
                      onClick={() => handleOpenChat(item.id)}
                      className="block w-full text-left hover:underline focus:outline-none focus:ring-2 focus:ring-white/10 rounded-sm transition"
                      title={item.name}
                    >
                      {item.name}
                    </button>
                  </li>
                ))
              )}
            </ul>
          )}
        </div>
      </aside>
    </nav>
  );
};

export default NavbarMenu;
