"use client";
import { create } from "zustand";
import { persist } from "zustand/middleware";

export const useChatStore = create(
  persist(
    (set) => ({
      messages: [],
      selectedModelIds: [],
      currentThreadId: null, // NEW

      setMessages: (v) =>
        set((s) => ({
          messages: typeof v === "function" ? v(s.messages) : v,
        })),
      addMessage: (m) => set((s) => ({ messages: [...s.messages, m] })),
      clearMessages: () => set({ messages: [], currentThreadId: null }), // reset cả thread
      setSelectedModelIds: (ids) =>
        set({ selectedModelIds: Array.from(new Set(ids)) }),
      setCurrentThreadId: (id) => set({ currentThreadId: id }), // NEW
    }),
    {
      name: "chat-store-v1",
      partialize: (s) => ({
        messages: s.messages,
        selectedModelIds: s.selectedModelIds,
        currentThreadId: s.currentThreadId,
      }),
    }
  )
);
